const fs = require('fs'); const crypto = require('crypto');
const { chromium } = require('D:/heypal-tools/test/pw/node_modules/playwright-core');
const ACC = 'D:/vi-tools/hf_account.txt';
(async () => {
  let pw;
  if (fs.existsSync(ACC)) { pw = JSON.parse(fs.readFileSync(ACC, 'utf8')).password; }
  else { pw = crypto.randomBytes(12).toString('base64').replace(/[^A-Za-z0-9]/g, 'x') + 'aA9!';
         fs.writeFileSync(ACC, JSON.stringify({ site: 'huggingface.co', email: '[REMOVED]', password: pw }, null, 1)); }
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9333');
  const ctx = browser.contexts()[0];
  const page = await ctx.newPage();
  await page.goto('https://huggingface.co/join', { waitUntil: 'domcontentloaded', timeout: 60000 });
  await page.waitForTimeout(2000);
  await page.fill('input[name="email"]', '[REMOVED]');
  await page.fill('input[name="password"]', pw);
  await page.click('button:has-text("Next")');
  await page.waitForTimeout(4000);
  console.log('URL:', page.url());
  const inputs = await page.evaluate(() => Array.from(document.querySelectorAll('input,select,textarea,button')).map(e => `${e.tagName} name=${e.name} type=${e.type} ph=${e.placeholder||''} txt=${(e.innerText||'').slice(0,40)}`));
  console.log(inputs.join('\n'));
  const txt = await page.evaluate(() => document.querySelector('main') ? document.querySelector('main').innerText.slice(0, 1500) : document.body.innerText.slice(0,1500));
  console.log(txt);
  await page.screenshot({ path: 'D:/vi-tools/hfauth/signup1.png', fullPage: true });
  // keep the tab open for step 2: record its target id
  process.exit(0);
})().catch(e => { console.error('ERR', e.message); process.exit(1); });
EOF
