const { chromium } = require('D:/heypal-tools/test/pw/node_modules/playwright-core');
(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9333');
  const page = await browser.contexts()[0].newPage();
  try {
    await page.goto('https://huggingface.co/settings/tokens/new?tokenType=read', { waitUntil: 'domcontentloaded', timeout: 60000 });
    await page.waitForTimeout(3000);
    const radios = await page.evaluate(() => Array.from(document.querySelectorAll('input[name=role]')).map(r => ({ v: r.value, c: r.checked, l: (r.closest('label') || r.parentElement).innerText.trim().slice(0, 30) })));
    console.log('radios', JSON.stringify(radios));
    const readR = radios.find(r => /^read$/i.test(r.v) || /^read/i.test(r.l));
    if (!readR) throw new Error('no read radio');
    await page.check(`input[name=role][value="${readR.v}"]`);
    await page.fill('input[name=displayName]', 'video-indexing-read');
    await page.click('button[type=submit]:has-text("Create token")');
    let tok = null;
    for (let i = 0; i < 20 && !tok; i++) {
      await page.waitForTimeout(1000);
      tok = await page.evaluate(() => {
        const re = /hf_[A-Za-z0-9]{30,}/;
        for (const e of document.querySelectorAll('input, textarea')) { const m = (e.value || '').match(re); if (m) return m[0]; }
        const m = document.body.innerText.match(re); return m ? m[0] : null;
      });
    }
    if (!tok) throw new Error('token not found on page, url=' + page.url());
    const dir = path.join(os.homedir(), '.cache', 'huggingface');
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, 'token'), tok);
    fs.writeFileSync(path.join(dir, 'stored_tokens'), `[video-indexing-read]\nhf_token = ${tok}\n\n`);
    console.log('token written to HF token store, length', tok.length);
  } finally { await page.close().catch(()=>{}); }
  process.exit(0);
})().catch(e => { console.error('ERR', e.message.replace(/hf_[A-Za-z0-9]{10,}/g, '[REMOVED]')); process.exit(1); });
