"""Fetch wheels from PyPI over a slow/flaky link: parallel, resumable curl via a pinned Fastly IP.

usage: python -I fetch_wheels.py OUTDIR PLATFORM_TAG name[==ver] ...
PLATFORM_TAG e.g. win_amd64 or manylinux
"""
import json, os, re, subprocess, sys
from concurrent.futures import ThreadPoolExecutor

IP = os.environ.get("PYPI_IP", "151.101.0.223")
OUT, PLAT, specs = sys.argv[1], sys.argv[2], sys.argv[3:]
os.makedirs(OUT, exist_ok=True)
META = os.path.join(OUT, "_meta"); os.makedirs(META, exist_ok=True)


def curl(url, dest, host, json_accept=False, maxtime=600):
    cmd = ["curl", "-s", "-4", "-L", "-C", "-", "--retry", "10", "--retry-delay", "2", "-m", str(maxtime),
           "--resolve", f"{host}:443:{IP}", "-o", dest, url]
    if json_accept:
        cmd[1:1] = ["-H", "Accept: application/vnd.pypi.simple.v1+json"]
    return subprocess.run(cmd).returncode


def vkey(v):
    return [int(x) if x.isdigit() else -1 for x in re.split(r"[.]", v)]


def pick(name, ver):
    norm = re.sub(r"[-_.]+", "-", name).lower()
    mp = os.path.join(META, norm + ".json")
    for _ in range(5):
        if os.path.exists(mp):
            try:
                d = json.load(open(mp, encoding="utf-8")); break
            except Exception:
                os.remove(mp)
        curl(f"https://pypi.org/simple/{norm}/", mp, "pypi.org", json_accept=True, maxtime=300)
    else:
        return name, None
    cands = {}
    for f in d["files"]:
        fn = f["filename"]
        if not fn.endswith(".whl") or f.get("yanked"):
            continue
        parts = fn[:-4].split("-")
        v, py, abi, plat = parts[1], parts[-3], parts[-2], parts[-1]
        if not re.fullmatch(r"[0-9.]+", v):
            continue  # skip pre-releases
        okpy = py in ("py3", "py2.py3", "cp311") or (abi == "abi3" and py.startswith("cp3") and int(py[3:] or 0) <= 11) \
            or ("cp311" in py.split("."))
        okplat = plat == "any" or (PLAT in plat)
        if okpy and okplat:
            cands.setdefault(v, []).append(f)
    if ver:
        vs = [ver] if ver in cands else []
    else:
        vs = sorted(cands, key=vkey)[-1:]
    if not vs:
        return name, None
    f = cands[vs[0]][0]
    return name, f


def fetch(spec):
    name, _, ver = spec.partition("==")
    name, f = pick(name, ver or None)
    if f is None:
        return f"NOWHEEL {spec}"
    dest = os.path.join(OUT, f["filename"])
    if os.path.exists(dest) and os.path.getsize(dest) == f.get("size", -1):
        return f"have {f['filename']}"
    url = f["url"].split("#")[0]
    for _ in range(20):
        curl(url, dest + ".part", "files.pythonhosted.org", maxtime=900)
        if os.path.exists(dest + ".part") and os.path.getsize(dest + ".part") == f.get("size", -2):
            os.replace(dest + ".part", dest)
            return f"ok {f['filename']}"
    return f"FAIL {f['filename']}"


with ThreadPoolExecutor(8) as ex:
    for r in ex.map(fetch, specs):
        print(r, flush=True)

