            img = to_bgr(fr)
            H, W = letterbox_shape(img.shape[0], img.shape[1])
            slot = get_slot()
            letterbox_into(img, slots[slot])
            send(("f", wid, vid, s, slot, H, W))

        for fr in c.decode(vs):
            t = clock.time(fr)
            if t < 0:
