import glob, zipfile, re
from packaging.requirements import Requirement
from packaging.utils import canonicalize_name
pins = {}
for l in open('D:/video-indexing/requirements.txt'):
    l = l.split('#')[0].strip()
    if l and not l.startswith('-'):
        n, v = l.split('==')
        pins[canonicalize_name(n)] = v
env = {'sys_platform': 'linux', 'platform_system': 'Linux', 'python_version': '3.11', 'platform_machine': 'x86_64', 'extra': ''}
problems = []
for w in glob.glob('wheels/*.whl') + glob.glob('wheels_torch/*.whl'):
    z = zipfile.ZipFile(w)
    meta = [n for n in z.namelist() if n.endswith('.dist-info/METADATA')][0]
    txt = z.read(meta).decode('utf-8', 'ignore')
    name = canonicalize_name(re.search(r'^Name: (.+)$', txt, re.M).group(1).strip())
    ver = re.search(r'^Version: (.+)$', txt, re.M).group(1).strip()
    if name not in pins or pins[name].split('+')[0] != ver.split('+')[0]:
        continue
    for line in re.findall(r'^Requires-Dist: (.+)$', txt, re.M):
        r = Requirement(line)
        if r.marker and not r.marker.evaluate(env):
            continue
        dn = canonicalize_name(r.name)
        if dn in pins and not r.specifier.contains(pins[dn].split('+')[0], prereleases=True):
            problems.append(f'{name} {ver} requires {r} but pin is {pins[dn]}')
print('checked pins:', sorted(pins)); print('conflicts:', problems or 'none')
EOF

